import { ChangeEvent, useEffect, useState } from "react";
import { CheckCircle2, FileText, MessageSquareWarning, Pencil, ShieldCheck, Sparkles, Trash2 } from "lucide-react";
import { Link, useLocation, useNavigate, useSearchParams } from "react-router-dom";
import { api } from "../api/client";
import { useProjectScope } from "../context/ProjectScope";
import { Badge, cardClass, confidenceLabel, formatDate, inputClass, jsonValue, LifecyclePipeline, ScopeBanner, StatePanel, StatusBadge } from "../components/KnowledgePrimitives";
import { PageHeader, Drawer } from "../components/ui";
import { CandidateReviewDetail } from "../components/CandidateReviewDetail";

type Section = "evidence" | "observations" | "candidates" | "cases" | "patterns" | "playbooks";
type JsonRecord = Record<string, unknown>;
type FactRecord = JsonRecord & { field?: string; value?: unknown; confirmed?: boolean };
type ReviewRecord = JsonRecord & { id: string; action: string; reason?: string; created_at?: string; reviewer_id?: string | number; before_json?: unknown; after_json?: unknown };
type NarrativeRecord = JsonRecord & { title?: string; summary?: string };
type CandidateCard = { [key: string]: unknown; facts?: unknown; summary?: string; problemStatement?: string; actions?: string[]; symptoms?: string[]; unknowns?: string[]; verification?: string[]; verificationPlan?: string[]; tags?: string[]; nextAction?: string; captureReasonText?: string; captureReason?: string; hypothesis?: string; verifiedConclusion?: string; displaySummary?: string; eventClass?: string; confidence?: unknown };
type KnowledgeDocument = { [key: string]: unknown; id: string; card?: CandidateCard; narrative?: NarrativeRecord; lifecycle?: string; title?: string; body?: string; metadata?: unknown; evidenceRefs?: string[]; caseRefs?: string[]; steps?: Array<string | JsonRecord>; scope?: { scopeType?: string; scopeKey?: string }; displayTitle?: string; displaySummary?: string; applicability?: string; symptoms?: string; rootCause?: string; fix?: string; verification?: string; rollback?: string; skillDiff?: string; updatedAt?: string; createdAt?: string; sourceLocator?: string; sourceCommit?: string; sourceSha256?: string; sourceCandidateId?: string; jobId?: string; deploymentId?: string; eventId?: string; confidence?: unknown; scopeType?: string; scopeKey?: string };
type KnowledgeRow = KnowledgeDocument & { humanStatus?: string; eventClass?: string; displayTitle?: string; displaySummary?: string; summary?: string; sampleManagerVersion?: string; module?: string; evidenceCount?: number; sourceKind?: string; retention?: string; environment?: string; jobId?: string; deploymentId?: string; createdAt?: string; sourceLocator?: string; locator?: string; deletedAt?: string; sizeBytes?: number; linkedCount?: number; sha256?: string };
type MetadataRecord = JsonRecord & { applicability?: string; trigger?: string; checks?: string; exceptions?: string; decisionTree?: string; decision_tree?: string; verification?: string[]; symptoms?: string[]; actions?: string[] };
type ApiPayload = JsonRecord & { evidence?: unknown; observations?: unknown; candidates?: unknown; documents?: unknown; linkedObjects?: unknown; sharedProjectIds?: unknown; reviews?: unknown[]; evidenceRefs?: unknown; document?: unknown };
type EvidenceRecord = JsonRecord & { id?: string; displayTitle?: string; displaySummary?: string; locator?: string; deletedAt?: string; sourceKind?: string; environment?: string; mimeType?: string; sizeBytes?: number; sha256?: string; retention?: string; linkedCount?: number; createdAt?: string };
type LinkedObject = JsonRecord & { id: string; type?: string; kind?: string; title?: string; lifecycle?: string };
type ObservationRecord = JsonRecord & { facts?: unknown; review?: unknown; displayTitle?: string; displaySummary?: string; humanStatus?: string; captureReasonText?: string; eventClass?: string; nextAction?: string; eventId?: string; sourceLocator?: string; sourceSha256?: string };
type ObservationReviewRecord = JsonRecord & { outcome?: string; reason?: string; reviewedAt?: string; nextReviewAt?: string; count?: number; ruleVersion?: string; candidateId?: string };
const asRecord = (value: unknown): JsonRecord => typeof value === "object" && value !== null ? value as JsonRecord : {};
const asText = (value: unknown, fallback = ""): string => typeof value === "string" ? value : value == null ? fallback : String(value);
const asRecords = (value: unknown): JsonRecord[] => Array.isArray(value) ? value.filter((item): item is JsonRecord => typeof item === "object" && item !== null) : [];
const asFacts = (value: unknown): FactRecord[] => asRecords(value).map((item) => item as FactRecord);
const asStringArray = (value: unknown): string[] => Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
const asReviews = (value: unknown): ReviewRecord[] => asRecords(value).filter((item): item is ReviewRecord => typeof item.id === "string" && typeof item.action === "string");
const asDocument = (value: unknown): KnowledgeDocument => asRecord(value) as KnowledgeDocument;
const sectionFor = (path: string): Section => path.includes("/evidence") ? "evidence" : path.includes("/observations") ? "observations" : path.includes("/candidates") ? "candidates" : path.includes("/cases") ? "cases" : path.includes("/patterns") ? "patterns" : "playbooks";

function EnvironmentPicker({ environment, setEnvironment }: { environment: string; setEnvironment: (value: string) => void }) {
  return <div className={`${cardClass} mb-4 flex flex-wrap items-center gap-3`}><label className="text-xs text-muted" htmlFor="knowledge-environment">Environment</label><input id="knowledge-environment" className={`${inputClass} w-40`} placeholder="production" value={environment} onChange={(event) => setEnvironment(event.target.value)} /><span className="text-xs text-muted">Project pages are ACL-filtered; changing environment reloads only this plane.</span></div>;
}

function Meta({ label, value }: { label: string; value: unknown }) { return <div className="min-w-0 rounded-panel border border-white/10 bg-black/20 p-3"><p className="text-xs text-muted">{label}</p><p className="mt-1 break-words text-sm text-fg">{String(value ?? "-")}</p></div>; }
function CardBlock({ title, value }: { title: string; value: unknown }) { return <div className="min-w-0 rounded-panel border border-white/10 bg-black/20 p-3"><p className="text-xs font-medium text-fg">{title}</p>{title === "Why captured" && <p className="mt-2 text-sm leading-6 text-sun/80">This is a review signal, not a confirmed problem. Approve only when linked Evidence proves a repeatable issue and a reusable fix. Otherwise reject it.</p>}<p className="mt-2 whitespace-pre-wrap break-words text-sm leading-6 text-muted">{String(value ?? "Not provided") || "Not provided"}</p></div>; }
function caseBusinessContext(doc: JsonRecord): JsonRecord | undefined {
  if (doc.businessContext && typeof doc.businessContext === "object") return doc.businessContext as JsonRecord;
  const text = [doc.title, doc.body, doc.symptoms, doc.rootCause, doc.fix].filter(Boolean).map((value) => String(value)).join(" ");
  if (/cache|formsbin|binform/i.test(text)) return { businessPurpose: "支持 SampleManager 表单快速加载，并保持表单定义与运行文件一致。", affectedProcess: "使用相关表单进行数据录入、结果处理或审核的业务流程。", businessImpact: "缓存过期或损坏可能导致表单打不开、显示旧版本或缺少控件，用户无法继续相关流程。", technicalComponentPurpose: "FormsBin / 表单运行缓存保存表单编译后的运行文件。", confidence: "inferred" };
  return undefined;
}
function BusinessContextBlock({ doc }: { doc: JsonRecord }) {
  const context = caseBusinessContext(doc);
  if (!context) return <section className="rounded-panel border border-sun/40 bg-sun/10 p-4"><h3 className="font-medium text-sun">业务场景尚未补齐</h3><p className="mt-2 text-sm leading-6 text-sun/80">当前 Case 只有技术描述。请补充它服务的业务流程、技术组件用途和实际影响，再将它推广为可复用 Pattern。</p></section>;
  return <section className="rounded-panel border border-iris/40 bg-iris/10 p-4"><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="font-medium text-iris">这条 Case 对应的业务场景</h3><span className="text-xs text-iris/70">{context.confidence === "provided" ? "来源提供" : "根据技术信号推断，需确认"}</span></div><div className="mt-3 grid gap-3 sm:grid-cols-2"><CardBlock title="业务用途" value={context.businessPurpose} /><CardBlock title="受影响流程" value={context.affectedProcess} /><CardBlock title="业务影响" value={context.businessImpact} /><CardBlock title="技术组件用途" value={context.technicalComponentPurpose} /></div></section>;
}
function ApprovalDecisionPanel({ card, evidenceRefs }: { card: JsonRecord; evidenceRefs: string[] }) {
  const facts = Array.isArray(card.facts) ? card.facts : [];
  // Keep the legacy action label discoverable for deep links and assistive tooling.
  const legacyApprovalLabel = "Accept & create Case";
  const assessment = candidateReadableAssessment(card, { lifecycle: "draft" });
  const routine = assessment.title.startsWith("Successful");
  return <section className={`rounded-panel border p-4 ${routine ? "border-mint/40 bg-mint/10" : "border-sun/40 bg-sun/10"}`}><span className="sr-only">{legacyApprovalLabel}</span><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-medium text-fg">What does this record mean?</h3><p className="mt-1 max-w-3xl text-sm leading-6 text-muted">{assessment.summary}</p></div><Badge tone={routine ? "green" : "amber"}>{routine ? "Routine check" : "Review evidence"}</Badge></div><div className="mt-4 grid gap-3 md:grid-cols-2"><CardBlock title="Recommended decision" value={assessment.decision} /><CardBlock title="Evidence and consequence" value={evidenceRefs.length ? `${evidenceRefs.length} Evidence item(s) are available. Approving creates a Case draft for investigation.` : "No Evidence is linked. Approval would have no source basis."} /></div><p className="mt-3 text-xs text-muted">A Case draft is not a verified conclusion.</p></section>;
}

function isRoutineInventory(value: unknown): boolean {
  const text = String(value ?? "").replace(/\s+/g, " ").trim();
  return /(?:^|\b)(?:log:\s*)?dir\s+[A-Za-z]:\\/i.test(text)
    && /\b(?:name|length|lastwritetime)\b/i.test(text)
    && /\bexists\s*=\s*(?:true|false)\b/i.test(text)
    && !/\b(?:error|failed|failure|warning|exception|timeout|denied|refused|missing|invalid)\b/i.test(text);
}

function candidateReadableAssessment(card: JsonRecord, document: JsonRecord): { title: string; summary: string; decision: string } {
  const facts = Array.isArray(card?.facts) ? card.facts : [];
  const status = String(facts.find((fact: unknown) => asRecord(fact).field === "status") ? asRecord(facts.find((fact: unknown) => asRecord(fact).field === "status")).value : document.lifecycle ?? "").toLowerCase();
  const factText = facts.map((fact: unknown) => String(asRecord(fact).value ?? "")).filter(Boolean);
  const raw = [card?.displayTitle, card?.displaySummary, card?.summary, card?.problemStatement, ...(Array.isArray(card?.symptoms) ? card.symptoms : []), ...factText].join(" ");
  const routine = (isRoutineInventory(raw) || factText.some(isRoutineInventory)) && /^(?:succeeded|success|completed|ok|passed)$/.test(status);
  const benign = /\b(?:build|execution|command)\s+succeeded\b[\s\S]*\b0\s+warnings?\b[\s\S]*\b0\s+errors?\b/i.test(raw);
  const signal = !benign && /\b(?:error|failed|failure|warning|warn|exception|timeout|denied|refused|unavailable|missing|invalid)\b/i.test(raw) && !routine;
  if (routine) return {
    title: "Successful server check; no problem found",
    summary: "The job completed successfully and returned a file listing from the SampleManager server. This is routine diagnostic information, not a failure or an incident.",
    decision: "Reject this Candidate. There is no problem to turn into a Case.",
  };
  if (signal) return {
    title: "A possible runtime problem needs review",
    summary: "The job reported a condition that may need investigation. Review the linked Evidence to confirm what happened and whether the same problem can happen again.",
    decision: "Approve only when the Evidence confirms a repeatable problem and a reusable fix.",
  };
  return {
    title: "No confirmed problem yet",
    summary: "This record contains operational output, but it does not by itself prove an incident, root cause, or reusable fix.",
    decision: "Do not approve until the Evidence shows a specific problem that needs a Case.",
  };
}
function FactTable({ facts }: { facts: FactRecord[] }) { if (!facts.length) return <p className="mt-2 text-sm text-muted">No confirmed facts recorded.</p>; return <details className="mt-2 overflow-x-auto"><summary className="cursor-pointer text-xs text-muted">Show {facts.length} source fields</summary><table className="mt-2 w-full text-left text-sm"><tbody>{facts.map((fact, index) => <tr key={index} className="border-t border-white/10"><th className="whitespace-nowrap px-2 py-2 text-xs font-medium text-muted">{fact.field ?? `Fact ${index + 1}`}</th><td className="px-2 py-2 break-words text-muted">{String(fact.value ?? fact ?? "-")}</td><td className="whitespace-nowrap px-2 py-2 text-[11px] text-subtle">{fact.confirmed === false ? "unconfirmed" : "source fact"}</td></tr>)}</tbody></table></details>; }

function EvidenceDetail({ id, onBack }: { id: string; onBack: () => void }) {
  const [data, setData] = useState<ApiPayload>(); const [error, setError] = useState("");
  useEffect(() => { api.knowledgeEvidence(id).then((result) => setData(result as ApiPayload)).catch((err) => setError(err instanceof Error ? err.message : "Evidence unavailable")); }, [id]);
  if (error) return <StatePanel state="error" message={error} />; if (!data) return <StatePanel state="loading" message="Loading Evidence metadata and ACL-controlled preview..." />;
  const evidence = asRecord(data.evidence) as EvidenceRecord;
  const linkedObjects = asRecords(data.linkedObjects).filter((item): item is LinkedObject => typeof item.id === "string");
  const sharedProjectIds = asStringArray(data.sharedProjectIds);
  return <div className="space-y-4"><button onClick={onBack} className="text-xs text-muted transition-colors hover:text-fg">-&gt; Back to Evidence</button><section className={cardClass}><div className="flex flex-wrap items-start justify-between gap-3"><div><Badge tone="mint">Raw Evidence</Badge><h3 className="mt-3 break-words text-xl font-semibold text-fg">{asText(evidence.displayTitle, "Captured operational evidence")}</h3><p className="mt-2 max-w-3xl text-sm leading-6 text-muted">{asText(evidence.displaySummary, "An immutable source artifact retained for traceability.")}</p><details className="mt-3"><summary className="cursor-pointer text-xs text-subtle">Technical details</summary><p className="mt-2 break-all text-xs text-subtle"><span className="block">{evidence.locator ?? evidence.id}</span><span className="mt-1 block">{evidence.id}</span></p></details></div><StatusBadge value={evidence.deletedAt ? "deleted" : "retained"} /></div><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Meta label="Source kind" value={evidence.sourceKind} /><Meta label="Environment" value={evidence.environment} /><Meta label="MIME / size" value={`${evidence.mimeType ?? "-"} / ${evidence.sizeBytes ?? "-"} bytes`} /><Meta label="SHA-256" value={evidence.sha256} /><Meta label="Retention" value={evidence.retention} /><Meta label="Linked objects" value={evidence.linkedCount} /><Meta label="Created" value={formatDate(evidence.createdAt)} /></div></section><section className={cardClass}><h3 className="font-medium text-fg">What happened and why it is saved</h3><p className="mt-2 text-sm leading-6 text-muted">This source artifact documents what happened during an execution. It is not a verified conclusion; linked knowledge objects are shown separately and filtered by your access.</p><div className="mt-4 grid gap-4 md:grid-cols-2"><div><p className="text-xs text-subtle">Linked Candidate / Case / Pattern / Playbook</p>{linkedObjects.length ? <div className="mt-2 space-y-2">{linkedObjects.map((object) => <Link key={`${object.type}-${object.id}`} to={`/knowledge/${object.kind === "candidate" ? "candidates" : object.kind === "case" ? "cases" : object.kind === "pattern" ? "patterns" : "playbooks"}?document=${encodeURIComponent(object.id)}`} className="block rounded-field border border-line bg-black/20 p-2 transition-colors hover:border-iris/60"><div className="flex flex-wrap items-center justify-between gap-2"><span className="text-xs text-fg">{object.title ?? object.id}</span><StatusBadge value={object.lifecycle ?? object.kind} /></div><span className="mt-1 block text-[11px] text-subtle">{object.kind} / {object.type}</span></Link>)}</div> : <p className="mt-2 text-sm text-subtle">No linked knowledge object yet.</p>}</div><div><p className="text-xs text-subtle">Shared project scope</p>{sharedProjectIds.length ? <div className="mt-2 flex flex-wrap gap-2">{sharedProjectIds.map((projectId) => <Badge key={projectId} tone="purple">Project {projectId}</Badge>)}</div> : <p className="mt-2 text-sm text-subtle">Private to its owning project.</p>}</div></div></section><section className={cardClass}><h3 className="font-medium text-fg">Safe preview</h3><p className="mt-2 text-sm leading-6 text-muted">Preview/download is recorded through an ACL-controlled session and the source bytes are never replaced by a summary.</p><button onClick={async () => { try { const session = await api.knowledgeEvidenceSession(id); window.open(`${api.knowledgeEvidenceContentUrl(id, session.sessionId)}`, "_blank", "noopener"); } catch (err) { setError(err instanceof Error ? err.message : "Unable to create preview session"); } }} className="mt-4 inline-flex items-center gap-2 rounded-ctl bg-mint px-3 py-2 text-xs font-medium text-ink transition hover:brightness-110"><ShieldCheck size={14} /> Open audited preview</button></section></div>;
}

function ObservationReview({ review }: { review: ObservationReviewRecord | undefined }) {
  return <section className={cardClass}>
    <h3 className="font-medium text-fg">Automatic review</h3>
    {!review ? <p className="mt-2 text-sm text-muted">Awaiting automatic review</p> : <>
      <p className="mt-2 break-words text-sm text-fg">{review.outcome === "promoted" ? "Draft Candidate created" : review.outcome === "deferred" ? "Retained for observation" : "Review failed; retry scheduled"}</p>
      <p className="mt-2 break-words text-sm text-muted">{review.reason}</p>
      <div className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        <Meta label="Last reviewed" value={formatDate(review.reviewedAt)} />
        <Meta label="Next review" value={review.nextReviewAt ? formatDate(review.nextReviewAt) : "Completed"} />
        <Meta label="Review attempts" value={review.count} /><Meta label="Rule version" value={review.ruleVersion} />
      </div>
      {review.candidateId && <Link className="mt-3 inline-flex max-w-full items-center gap-2 break-all text-sm text-iris transition-colors hover:text-fg" to={`/knowledge/candidates?document=${encodeURIComponent(review.candidateId)}`}><FileText size={16} className="shrink-0" />Open draft Candidate</Link>}
    </>}
  </section>;
}

function ObservationDetail({ id, onBack }: { id: string; onBack: () => void }) {
  const [data, setData] = useState<ApiPayload>(); const [error, setError] = useState("");
  useEffect(() => {
    let active = true;
    const refresh = () => api.knowledgeObservation(id).then((result) => { if (active) { setData(result as ApiPayload); setError(""); } }).catch((err) => { if (active) setError(err instanceof Error ? err.message : "Observation unavailable"); });
    void refresh();
    const timer = window.setInterval(() => { void refresh(); }, 10_000);
    return () => { active = false; window.clearInterval(timer); };
  }, [id]);
  if (error) return <StatePanel state="error" message={error} />; if (!data) return <StatePanel state="loading" message="Loading runtime observation..." />;
  const observation = asRecord(data.observation) as ObservationRecord; const facts = asFacts(observation.facts);
  return <div className="space-y-4"><button onClick={onBack} className="text-xs text-muted transition-colors hover:text-fg">-&gt; Back to Observations</button><section className={cardClass}><div className="flex flex-wrap items-start justify-between gap-3"><div><Badge tone="sun">Runtime Observation</Badge><h3 className="mt-3 break-words text-xl font-semibold text-fg">{asText(observation.displayTitle)}</h3><p className="mt-2 max-w-3xl text-sm leading-6 text-muted">{asText(observation.displaySummary)}</p></div><StatusBadge value={asText(observation.humanStatus)} /></div><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Meta label="Why saved" value={observation.captureReasonText} /><Meta label="Event class" value={observation.eventClass} /><Meta label="Next action" value={observation.nextAction} /><Meta label="Event ID" value={observation.eventId} /></div></section><ObservationReview review={asRecord(observation.review) as ObservationReviewRecord} /><section className={cardClass}><h3 className="font-medium text-fg">Observed facts</h3><FactTable facts={facts} /></section><section className={cardClass}><h3 className="font-medium text-fg">What happens next</h3><p className="mt-2 text-sm leading-6 text-muted">An Observation records facts without asserting a root cause. A reviewer may use its linked Evidence to create a Candidate when a concrete problem signal is confirmed.</p><details className="mt-4"><summary className="cursor-pointer text-xs text-subtle">Technical provenance</summary><p className="mt-2 break-all text-xs text-subtle"><span className="block">{observation.sourceLocator}</span><span className="mt-1 block">{observation.sourceSha256 ?? "hash unavailable"}</span></p></details></section></div>;
}

function EvidenceLinkEditor({ documentId, evidenceRefs, onChanged }: { documentId: string; evidenceRefs: string[]; onChanged: () => Promise<void> }) {
  const [evidenceId, setEvidenceId] = useState(""); const [reason, setReason] = useState(""); const [busy, setBusy] = useState(""); const [error, setError] = useState("");
  const submit = async (operation: "attach" | "detach") => { if (!evidenceId.trim() || !reason.trim()) { setError("Evidence ID and an audit reason are required."); return; } setBusy(operation); setError(""); try { await api.knowledgeDocumentEvidence(documentId, { evidenceId: evidenceId.trim(), operation, reason: reason.trim() }, `knowledge-evidence-link:${documentId}:${operation}:${evidenceId.trim()}:${Date.now()}`); setEvidenceId(""); setReason(""); await onChanged(); } catch (err) { setError(err instanceof Error ? err.message : "Evidence link update failed"); } finally { setBusy(""); } };
  return <section className="rounded-panel border border-line bg-black/20 p-3"><div className="flex flex-wrap items-center justify-between gap-2"><div><h4 className="text-xs font-medium text-fg">Manage Evidence links</h4><p className="mt-1 text-xs text-subtle">Attach or unlink an Evidence ID with a required audit reason. Source bytes remain immutable.</p></div><Badge tone="mint">{evidenceRefs.length} linked</Badge></div><div className="mt-3 grid gap-2 sm:grid-cols-[minmax(0,1fr)_minmax(0,1fr)_auto_auto]"><input className={inputClass} placeholder="Evidence ID" value={evidenceId} onChange={(event) => setEvidenceId(event.target.value)} /><input className={inputClass} placeholder="Reason (required)" value={reason} onChange={(event) => setReason(event.target.value)} /><button disabled={!!busy} onClick={() => submit("attach")} className="rounded-ctl bg-mint px-3 py-2 text-xs font-medium text-ink transition hover:brightness-110 disabled:opacity-50">{busy === "attach" ? "Attaching…" : "Attach"}</button><button disabled={!!busy} onClick={() => submit("detach")} className="rounded-ctl border border-coral/40 bg-coral/10 px-3 py-2 text-xs text-coral transition hover:bg-coral/20 disabled:opacity-50">{busy === "detach" ? "Unlinking…" : "Unlink"}</button></div>{error && <p className="mt-2 break-words text-xs text-coral">{error}</p>}{evidenceRefs.length > 0 && <p className="mt-2 break-all text-xs text-subtle">Linked: {evidenceRefs.join(", ")}</p>}</section>;
}

function KnowledgeDetail({ id, projectId, kind, onBack, onReview }: { id: string; projectId: number; kind: string; onBack: () => void; onReview: (action: string, reason: string, payload?: Record<string, unknown>) => Promise<void> }) {
  const [data, setData] = useState<ApiPayload>(); const [error, setError] = useState(""); const [reason, setReason] = useState(""); const [actionBusy, setActionBusy] = useState(""); const [editOpen, setEditOpen] = useState(false); const [editSummary, setEditSummary] = useState("");
  const load = async () => { const result = await api.knowledgeDocument(id, projectId) as ApiPayload; setData(result); const document = asDocument(result.document); const card = asRecord(document.card); setEditSummary(asText(card.summary ?? document.body)); };
  useEffect(() => { load().catch((err) => setError(err instanceof Error ? err.message : "Knowledge document unavailable")); }, [id, projectId]);
  if (error) return <StatePanel state="error" message={error} />; if (!data) return <StatePanel state="loading" message="Loading structured Knowledge detail and review history..." />;
  const doc = asDocument(data.document); const card = (doc.card ?? {}) as CandidateCard; const metadata = asRecord(jsonValue(doc.metadata, {})) as MetadataRecord; const facts = asFacts(card.facts); const evidenceRefs = asStringArray(data.evidenceRefs);
  const runAction = async (action: string, overridePayload?: Record<string, unknown>) => { if (!reason.trim()) { setError("Enter an audit reason before changing lifecycle."); return; } setActionBusy(action); try { const payload = overridePayload ?? (action === "promote" ? { sourceId: id, patternId: `pattern-${id}`, patternTitle: `Pattern: ${doc.title}`, patternBody: doc.body } : action === "edit_card" ? { card: { summary: editSummary } } : undefined); await onReview(action, reason, payload); setReason(""); setEditOpen(false); await load(); } catch (err) { setError(err instanceof Error ? err.message : "Review action failed"); } finally { setActionBusy(""); } };
  if (kind === "Candidates") return <CandidateReviewDetail document={{ ...doc, card: card as CandidateCard, narrative: undefined }} evidenceRefs={evidenceRefs} reviews={asReviews(data.reviews)} onBack={onBack} onReview={onReview} refresh={load} evidenceEditor={<EvidenceLinkEditor documentId={id} evidenceRefs={evidenceRefs} onChanged={load} />} />;
  const structuredKind = kind === "Cases" ? <><BusinessContextBlock doc={doc} /><CardBlock title="Problem / summary" value={doc.body ?? doc.title} /><CardBlock title="Symptoms" value={doc.symptoms} /><CardBlock title="Root cause / verified only" value={doc.rootCause ?? "Not verified"} /><CardBlock title="Fix / actions" value={doc.fix} /><CardBlock title="Verification / next step" value={doc.verification} /><CardBlock title="Applicability / boundaries" value={doc.applicability} /></> : kind === "Patterns" ? <><CardBlock title="If / Then pattern" value={doc.body ?? card.summary} /><CardBlock title="Applicability / boundaries" value={doc.applicability ?? metadata.applicability} /><CardBlock title="Supporting Cases" value={(doc.caseRefs ?? []).join("\n") || "No supporting Cases linked."} /><CardBlock title="Supporting Evidence" value={(doc.evidenceRefs ?? evidenceRefs).join("\n") || "No Evidence linked."} /><CardBlock title="Trigger / checks / exceptions" value={metadata.trigger ?? metadata.checks ?? metadata.exceptions ?? "Not provided"} /></> : kind === "Playbooks" ? <><CardBlock title="Goal" value={doc.body ?? card.summary} /><CardBlock title="Preconditions" value={doc.applicability ?? metadata.applicability} /><CardBlock title="Decision points" value={metadata.decisionTree ?? metadata.decision_tree ?? "Not provided"} /><CardBlock title="Execution steps" value={(doc.steps ?? []).map((step, index) => `${index + 1}. ${typeof step === "string" ? step : step?.description ?? step?.command ?? "Step details unavailable"}`).join("\n") || "No steps recorded."} /><CardBlock title="Expected result / verification standard" value={metadata.verification ?? card.verification ?? "Not provided"} /><CardBlock title="Rollback" value={doc.rollback ?? "Not provided"} /><CardBlock title="Related Pattern / Case / Evidence" value={[(doc.caseRefs ?? []).join(", "), (doc.evidenceRefs ?? evidenceRefs).join(", ")].filter(Boolean).join("\n") || "No source links recorded."} /><CardBlock title="Proposed Skill diff" value={doc.skillDiff ?? "No Skill diff proposal."} /></> : <><CardBlock title="Problem / summary" value={card.problemStatement ?? card.summary ?? doc.body} /><CardBlock title="Symptoms" value={(card.symptoms ?? metadata.symptoms ?? []).join?.("\n") ?? metadata.symptoms} /><div className="min-w-0 rounded-panel border border-line bg-black/20 p-3"><p className="text-xs font-medium text-fg">Confirmed facts</p><FactTable facts={facts} /></div><CardBlock title="Unknowns" value={(card.unknowns ?? ["Root cause has not been verified."]).join("\n")} /><CardBlock title="Root cause / verified only" value={card.verifiedConclusion ?? "Not verified"} /><CardBlock title="Fix / actions" value={(card.actions ?? metadata.actions ?? []).join?.("\n") ?? metadata.actions} /><CardBlock title="Verification / next step" value={[(card.verification ?? card.verificationPlan ?? metadata.verification ?? []).join?.("\n") ?? metadata.verification, card.nextAction ? `Next action: ${card.nextAction}` : ""].filter(Boolean).join("\n")} /></>;
  const readableAssessment = kind === "Candidates" ? candidateReadableAssessment(card, doc) : undefined;
  const humanTitle = readableAssessment?.title ?? doc.displayTitle ?? (kind === "Cases" ? doc.title || "Case record" : kind === "Patterns" ? "Reusable Pattern" : kind === "Playbooks" ? "Executable Playbook" : doc.title);
  const humanSummary = readableAssessment?.summary ?? doc.displaySummary ?? card.displaySummary ?? card.summary ?? "Structured Knowledge record";
  return <div className="space-y-4"><button onClick={onBack} className="inline-flex items-center gap-2 text-xs text-muted transition-colors hover:text-fg">-&gt; Back to {kind}</button><section className={cardClass}><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex flex-wrap items-center gap-2"><Badge tone="purple">{kind.slice(0, -1)}</Badge><StatusBadge value={doc.lifecycle} />{card.eventClass && <Badge tone="sun">{String(card.eventClass).replaceAll("_", " ")}</Badge>}</div><h3 className="mt-3 break-words text-xl font-semibold text-fg">{humanTitle}</h3><p className="mt-2 max-w-3xl break-words text-sm leading-6 text-muted">{humanSummary}</p><details className="mt-3"><summary className="cursor-pointer text-xs text-subtle">Technical provenance</summary><p className="mt-3 break-all text-xs text-subtle">{doc.sourceLocator}</p></details></div><div className="text-right text-xs text-subtle"><p>Updated {formatDate(doc.updatedAt)}</p><p className="mt-1">Created {formatDate(doc.createdAt)}</p></div></div><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Meta label="Scope" value={`${doc.scope?.scopeType ?? doc.scopeType ?? "project"} / ${doc.scope?.scopeKey ?? doc.scopeKey ?? "-"}`} /><Meta label="Environment" value={doc.environment} /><Meta label="Source commit" value={doc.sourceCommit} /><Meta label="Source SHA-256" value={doc.sourceSha256} /><Meta label="Source Candidate" value={doc.sourceCandidateId} /><Meta label="Job / deployment" value={[doc.jobId, doc.deploymentId].filter(Boolean).join(" / ")} /><Meta label="Confidence" value={confidenceLabel(doc.confidence ?? card.confidence)} /></div></section>{kind === "Candidates" && <ApprovalDecisionPanel card={card} evidenceRefs={evidenceRefs} />}{kind === "Candidates" && <section className={cardClass}><h3 className="font-medium text-fg">Candidate Card</h3><div className="mt-4 space-y-4"><CardBlock title="Why captured" value={card.captureReasonText ?? card.captureReason ?? "No capture reason recorded."} /><CardBlock title="Summary" value={card.displaySummary ?? card.summary ?? doc.body} /><CardBlock title="Problem statement" value={card.problemStatement} /><div className="min-w-0 rounded-panel border border-line bg-black/20 p-3"><p className="text-xs font-medium text-fg">Confirmed facts</p><FactTable facts={facts} /></div><CardBlock title="Unknowns" value={(card.unknowns ?? ["Root cause has not been verified."]).join("\n")} /><CardBlock title="Symptoms" value={(card.symptoms ?? []).join("\n")} /><CardBlock title="Hypothesis / unconfirmed" value={card.hypothesis} /><CardBlock title="Verification plan" value={(card.verificationPlan ?? []).join("\n")} /><CardBlock title="Next action" value={card.nextAction ?? card.actions?.[0] ?? "Review the linked Evidence and reproduce the event."} /><CardBlock title="Linked Evidence" value={evidenceRefs.join("\n") || "No Evidence linked yet."} /><CardBlock title="Raw Event provenance" value={[doc.eventId, doc.jobId, doc.deploymentId].filter(Boolean).join("\n") || "No event provenance recorded."} /></div><div className="mt-4 flex flex-wrap gap-2"><Badge tone="purple">{confidenceLabel(card.confidence)}</Badge>{(card.tags ?? []).map((tag: string) => <Badge key={tag}>{tag}</Badge>)}</div></section>}{kind !== "Candidates" && <section className={cardClass}><h3 className="font-medium text-fg">{kind === "Cases" ? "Case record" : kind === "Patterns" ? "Generalizable pattern" : "Executable playbook"}</h3><div className="mt-3 grid gap-4 md:grid-cols-2">{structuredKind}</div></section>}{["Candidates", "Cases", "Patterns", "Playbooks"].includes(kind) && <EvidenceLinkEditor documentId={id} evidenceRefs={evidenceRefs} onChanged={load} />}<section className={cardClass}><div className="flex items-center justify-between"><h3 className="font-medium text-fg">Review and traceability</h3><span className="text-xs text-subtle">Before/after snapshots are retained in audit</span></div><div className="mt-3 space-y-2">{(data.reviews ?? []).length === 0 ? <p className="text-sm text-subtle">No review actions recorded.</p> : asReviews(data.reviews).map((review) => <details key={review.id} className="rounded-panel border border-line bg-black/10 p-3"><summary className="cursor-pointer list-none"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-sm text-fg">{review.action}</p><p className="mt-1 text-xs text-subtle"><span className="block">{review.reason}</span><span className="mt-1 block">{formatDate(review.created_at)}</span></p></div><Badge>{review.reviewer_id ? `reviewer #${review.reviewer_id}` : "system"}</Badge></div></summary><div className="mt-3 grid gap-2 text-[11px] sm:grid-cols-2"><pre className="max-h-40 overflow-auto whitespace-pre-wrap break-words rounded-field border border-line bg-[var(--field)] p-2 text-subtle">{JSON.stringify(jsonValue(review.before_json, {}), null, 2)}</pre><pre className="max-h-40 overflow-auto whitespace-pre-wrap break-words rounded-field border border-line bg-[var(--field)] p-2 text-subtle">{JSON.stringify(jsonValue(review.after_json, {}), null, 2)}</pre></div></details>)}</div><div className="mt-4 border-t border-line pt-4"><textarea className="min-h-20 w-full rounded-field border border-line bg-[var(--field)] p-3 text-sm text-fg outline-none transition placeholder:text-muted/70 focus:border-mint focus:ring-2 focus:ring-mint/20" placeholder="Reason for this lifecycle action (required for audit)" value={reason} onChange={(e) => setReason(e.target.value)} />{kind === "Candidates" && editOpen && <textarea className="mt-3 min-h-20 w-full rounded-field border border-iris/60 bg-[var(--field)] p-3 text-sm text-fg outline-none transition focus:border-iris focus:ring-2 focus:ring-iris/20" placeholder="Edit deterministic card summary" value={editSummary} onChange={(e) => setEditSummary(e.target.value)} />}<div className="mt-3 flex flex-wrap gap-2">{kind === "Candidates" && <><button disabled={!!actionBusy} onClick={() => runAction("accept")} className="inline-flex items-center gap-2 rounded-ctl bg-mint px-3 py-2 text-xs font-medium text-ink transition hover:brightness-110 disabled:opacity-50"><CheckCircle2 size={14} />{actionBusy ? "Saving..." : "Approve Candidate -> create Case draft"}</button><button disabled={!!actionBusy} onClick={() => { setEditOpen((open) => !open); if (editOpen) void runAction("edit_card"); }} className="inline-flex items-center gap-2 rounded-ctl border border-iris/40 bg-iris/10 px-3 py-2 text-xs text-iris transition hover:bg-iris/20 disabled:opacity-50"><Pencil size={14} />{editOpen ? "Save Card" : "Edit Card"}</button></>} {kind === "Cases" && <><button disabled={!!actionBusy || !["verified", "approved"].includes(String(doc.lifecycle))} onClick={() => runAction("promote")} className="inline-flex items-center gap-2 rounded-ctl bg-mint px-3 py-2 text-xs font-medium text-ink transition hover:brightness-110 disabled:opacity-50"><Sparkles size={14} />Promote Pattern</button>{doc.lifecycle === "draft" && <button disabled={!!actionBusy} onClick={() => runAction("review", { lifecycle: "reproduced" })} className="inline-flex items-center gap-2 rounded-ctl border border-iris/40 bg-iris/10 px-3 py-2 text-xs text-iris transition hover:bg-iris/20 disabled:opacity-50"><CheckCircle2 size={14} />Mark reproduced</button>}{doc.lifecycle === "reproduced" && <button disabled={!!actionBusy} onClick={() => runAction("review", { lifecycle: "verified" })} className="inline-flex items-center gap-2 rounded-ctl border border-iris/40 bg-iris/10 px-3 py-2 text-xs text-iris transition hover:bg-iris/20 disabled:opacity-50"><CheckCircle2 size={14} />Mark verified</button>}</>}{(kind === "Patterns" || kind === "Playbooks") && <button disabled={!!actionBusy} onClick={() => runAction("review", { lifecycle: "approved" })} className="inline-flex items-center gap-2 rounded-ctl bg-mint px-3 py-2 text-xs font-medium text-ink transition hover:brightness-110 disabled:opacity-50"><CheckCircle2 size={14} />Approve</button>}<button disabled={!!actionBusy} onClick={() => runAction("deprecate")} className="inline-flex items-center gap-2 rounded-ctl border border-coral/40 bg-coral/10 px-3 py-2 text-xs text-coral transition hover:bg-coral/20 disabled:opacity-50"><Trash2 size={14} />Deprecate</button><button disabled={!!actionBusy} onClick={() => runAction("reject")} className="inline-flex items-center gap-2 rounded-ctl border border-line px-3 py-2 text-xs text-muted transition hover:bg-white/[.06] hover:text-fg disabled:opacity-50"><MessageSquareWarning size={14} />Reject candidate</button></div></div></section>{error && <p className="rounded-field border border-coral/40 bg-coral/10 p-3 text-sm text-coral">{error}</p>}</div>;
}

function EvidenceListRow({ row, onSelect }: { row: KnowledgeRow; onSelect: (id: string) => void }) {
  return <button onClick={() => onSelect(row.id)} className="glass block w-full rounded-panel border-line p-4 text-left transition-colors hover:border-mint/50"><div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0"><div className="flex min-w-0 items-center gap-2"><ShieldCheck size={16} className="shrink-0 text-mint" /><p className="break-words text-sm font-medium text-fg">{row.displayTitle ?? "Captured operational evidence"}</p></div><p className="mt-2 break-words text-sm leading-6 text-muted">{row.displaySummary ?? "An immutable source artifact retained for traceability."}</p><details className="mt-2"><summary className="cursor-pointer text-[11px] text-subtle">Technical details</summary><p className="mt-1 break-all text-[11px] text-subtle"><span className="block">{row.locator ?? row.id}</span><span className="mt-1 block">{row.id}</span></p></details></div><StatusBadge value={row.deletedAt ? "deleted" : "retained"} /></div><div className="mt-3 grid gap-2 text-xs text-subtle sm:grid-cols-2 lg:grid-cols-4"><span>Source: {row.sourceKind ?? "unknown"}</span><span>Environment: {row.environment ?? "unknown"}</span><span>Size: {row.sizeBytes ?? "-"} bytes</span><span>Linked: {row.linkedCount ?? 0} object(s)</span><span className="break-all">SHA-256: {row.sha256 ?? "unavailable"}</span><span>Retention: {row.retention ?? "standard"}</span><span>Created: {formatDate(row.createdAt)}</span></div></button>;
}

function ObservationListRow({ row, onSelect }: { row: KnowledgeRow; onSelect: (id: string) => void }) {
  return <button onClick={() => onSelect(row.id)} className="glass block w-full rounded-panel border-line p-4 text-left transition-colors hover:border-sun/50"><div className="flex flex-wrap items-center justify-between gap-3"><div className="min-w-0"><div className="flex items-center gap-2"><MessageSquareWarning size={16} className="shrink-0 text-sun" /><p className="break-words text-sm font-medium text-fg">{row.displayTitle}</p></div><p className="mt-2 break-words text-sm leading-6 text-muted">{row.displaySummary}</p></div><StatusBadge value={row.humanStatus} /></div><div className="mt-3 flex flex-wrap gap-3 text-xs text-subtle"><span>Event: {row.eventId}</span><span>Class: {row.eventClass}</span><span>Evidence: {row.evidenceRefs?.length ?? 0}</span><span>Updated: {formatDate(row.updatedAt)}</span></div></button>;
}

function DocumentListRow({ row, section, onSelect }: { row: KnowledgeRow; section: Section; onSelect: (id: string) => void }) {
 if (section === "candidates" && row.card) {
    row.displayTitle = row.narrative?.title ?? candidateReadableAssessment(row.card, row).title;
    row.displaySummary = row.narrative?.summary ?? candidateReadableAssessment(row.card, row).summary;
 }
  return <button onClick={() => onSelect(row.id)} className="glass block w-full rounded-panel border-line p-4 text-left transition-colors hover:border-iris/50"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex min-w-0 items-center gap-2"><FileText size={16} className="shrink-0 text-iris" /><p className="break-words text-sm font-medium text-fg">{row.displayTitle ?? row.title ?? row.id}</p></div><div className="flex flex-wrap items-center gap-2"><StatusBadge value={row.lifecycle} />{row.eventClass && <Badge tone="sun">{String(row.eventClass).replaceAll("_", " ")}</Badge>}</div></div><p className="mt-2 break-words text-sm leading-6 text-muted">{row.displaySummary ?? row.summary ?? row.body?.slice(0, 350) ?? "No summary available"}</p><div className="mt-3 flex flex-wrap gap-3 text-xs text-subtle"><span>Updated: {formatDate(row.updatedAt)}</span><span>Scope: {row.scope?.scopeType ?? row.scopeType ?? "project"}</span><span>Version: {row.sampleManagerVersion ?? "general"}</span><span>Module: {row.module ?? "general"}</span>{row.evidenceCount !== undefined && <span>Evidence: {row.evidenceCount}</span>}{section === "patterns" && <span>Supporting Cases: {row.caseRefs?.length ?? 0}</span>}{section === "playbooks" && <span>Steps: {row.steps?.length ?? 0}</span>}{row.confidence !== undefined && <span>Confidence: {Math.round(Number(row.confidence) * 100)}%</span>}</div></button>;
}

function ProjectList({ section, projectId, environment, onSelect }: { section: Section; projectId: number; environment: string; onSelect: (id: string) => void }) {
  const [params, setParams] = useSearchParams(); const [rows, setRows] = useState<KnowledgeRow[]>([]); const [error, setError] = useState(""); const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState(() => ({ sourceKind: params.get("sourceKind") ?? "", retention: params.get("retention") ?? "", environment: params.get("environment") ?? "", jobId: params.get("jobId") ?? "", deploymentId: params.get("deploymentId") ?? "", status: params.get("status") ?? "", candidateType: params.get("candidateType") ?? "", sampleManagerVersion: params.get("sampleManagerVersion") ?? "", solution: params.get("solution") ?? "", module: params.get("module") ?? "", minEvidenceCount: params.get("minEvidenceCount") ?? "", createdAfter: params.get("createdAfter") ?? "", createdBefore: params.get("createdBefore") ?? "" }));
  const load = () => { setLoading(true); setError(""); const query = new URLSearchParams(params); Object.entries(filters).forEach(([key, value]) => value ? query.set(key, value) : query.delete(key)); if (environment) query.set("environment", environment); setParams(query, { replace: true }); const requestEnvironment = environment; const evidenceParams = { sourceKind: filters.sourceKind, retention: filters.retention, environment: requestEnvironment, jobId: filters.jobId, deploymentId: filters.deploymentId, createdAfter: filters.createdAfter, createdBefore: filters.createdBefore }; const candidateParams = { candidateType: filters.candidateType, sampleManagerVersion: filters.sampleManagerVersion, solution: filters.solution, module: filters.module, environment: requestEnvironment, minEvidenceCount: filters.minEvidenceCount, createdAfter: filters.createdAfter, createdBefore: filters.createdBefore }; const task = section === "evidence" ? api.knowledgeEvidenceList(projectId, evidenceParams) : section === "observations" ? api.knowledgeObservations(projectId, { ...filters, environment: requestEnvironment }) : section === "candidates" ? api.knowledgeCandidates(projectId, filters.status || undefined, candidateParams) : api.knowledgeDocuments(projectId, section === "cases" ? "case" : section === "patterns" ? "pattern" : "playbook", { environment: requestEnvironment }); task.then((result) => { const payload = typeof result === "object" && result !== null ? result as Record<string, unknown> : {}; const value = payload.evidence ?? payload.observations ?? payload.candidates ?? payload.documents; setRows(Array.isArray(value) ? value : []); }).catch((err) => setError(err instanceof Error ? err.message : "Unable to load Project Knowledge")).finally(() => setLoading(false)); };
  useEffect(() => { setFilters((current) => ({ ...current, environment })); }, [environment]);
  useEffect(() => { load(); }, [section, projectId, environment]);
  const setFilter = (key: keyof typeof filters) => (event: ChangeEvent<HTMLInputElement | HTMLSelectElement>) => setFilters((old) => ({ ...old, [key]: event.target.value }));
  const filterPanel = section === "evidence" ? <div className={`${cardClass} mb-4`}><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><input className={inputClass} placeholder="Source kind" value={filters.sourceKind} onChange={setFilter("sourceKind")} /><select className={inputClass} value={filters.retention} onChange={setFilter("retention")}><option value="">Retention</option><option value="standard">standard</option><option value="legal_hold">legal hold</option><option value="gmp_hold">GMP hold</option></select><input className={inputClass} placeholder="Job ID" value={filters.jobId} onChange={setFilter("jobId")} /><input className={inputClass} placeholder="Deployment ID" value={filters.deploymentId} onChange={setFilter("deploymentId")} /></div><div className="mt-2 flex justify-end"><button onClick={load} className="rounded-ctl bg-mint px-3 py-2 text-xs font-medium text-ink transition hover:brightness-110">Apply Evidence filters</button></div></div> : section === "candidates" ? <div className={`${cardClass} mb-4`}><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><select className={inputClass} value={filters.status} onChange={setFilter("status")}><option value="">All active lifecycles</option><option value="draft">draft</option><option value="reproduced">reproduced</option><option value="verified">verified</option><option value="approved">approved</option></select><select className={inputClass} value={filters.candidateType} onChange={setFilter("candidateType")}><option value="">Candidate type</option><option value="case">case</option><option value="pattern">pattern</option><option value="playbook">playbook</option></select><input className={inputClass} placeholder="Version" value={filters.sampleManagerVersion} onChange={setFilter("sampleManagerVersion")} /><input className={inputClass} placeholder="Solution" value={filters.solution} onChange={setFilter("solution")} /><input className={inputClass} placeholder="Module" value={filters.module} onChange={setFilter("module")} /></div><div className="mt-2 flex justify-end"><button onClick={load} className="rounded-ctl bg-mint px-3 py-2 text-xs font-medium text-ink transition hover:brightness-110">Apply Candidate filters</button></div></div> : null;
  if (loading) return <>{filterPanel}<StatePanel state="loading" message={`Loading ${section} for this project...`} /></>; if (error) return <>{filterPanel}<StatePanel state="error" message={error} onRetry={load} /></>; if (!rows.length) return <>{filterPanel}<StatePanel state="empty" message={`No ${section} records exist in this project yet. The page remains available so the scope and workflow are clear before the first record arrives.`} /></>;
  return <>{filterPanel}<div className="space-y-3">{rows.map((row) => section === "evidence" ? <EvidenceListRow key={row.id} row={row} onSelect={onSelect} /> : section === "observations" ? <ObservationListRow key={row.id} row={row} onSelect={onSelect} /> : <DocumentListRow key={row.id} row={row} section={section} onSelect={onSelect} />)}</div></>;
}

export default function KnowledgeProject() {
  const section = sectionFor(useLocation().pathname);
  const navigate = useNavigate();
  const [params, setParams] = useSearchParams();
  const selected = params.get("document");
  const { projectId, selectedProject, loading: scopeLoading, error: scopeError } = useProjectScope();
  const environment = params.get("environment") ?? localStorage.getItem("knowledge.environment") ?? "production";
  const selectEnvironment = (value: string) => {
    localStorage.setItem("knowledge.environment", value);
    setParams((current) => {
      const next = new URLSearchParams(current);
      if (value) next.set("environment", value);
      else next.delete("environment");
      return next;
    }, { replace: true });
  };
  const review = async (action: string, reason: string, payload?: Record<string, unknown>) => {
    if (!selected) throw new Error("A Knowledge document must be selected before review.");
    await api.knowledgeReview({ action, documentId: selected, reason, ...(payload ?? {}) }, `ui-${action}-${selected}-${Date.now()}`);
  };
  const title = section === "evidence" ? "Evidence" : section === "observations" ? "Observations" : section === "candidates" ? "Candidate insights" : section === "cases" ? "Cases" : section === "patterns" ? "Patterns" : "Playbooks";
  const detailKind = section === "candidates" ? "Candidates" : section === "cases" ? "Cases" : section === "patterns" ? "Patterns" : section === "playbooks" ? "Playbooks" : title;
  const listPath = (targetSection: string) => {
    const next = new URLSearchParams(params);
    next.delete("document");
    const query = next.toString();
    return `/knowledge/${targetSection}${query ? `?${query}` : ""}`;
  };
  const description = section === "evidence" ? "Immutable source artifacts with ACL-controlled preview and traceability." : section === "observations" ? "Runtime facts and warnings that have not yet become a confirmed problem." : "Project records remain readable here. Use the Memory workspace for durable knowledge.";
  return <div className="mx-auto max-w-[1280px] px-5 py-8 sm:px-8">
    <PageHeader title={title} description={description} />
    <EnvironmentPicker environment={environment} setEnvironment={selectEnvironment} />
    {scopeError && <p className="mb-4 rounded-field border border-coral/40 bg-coral/10 p-3 text-sm text-coral">{scopeError}</p>}
    <ScopeBanner project={selectedProject?.name} environment={environment} scope="project runtime" acl="owner / granted reviewers" />
    <LifecyclePipeline current={section === "evidence" ? "Evidence" : section === "observations" ? "Observations" : undefined} />
    <nav className="mt-5 flex flex-wrap gap-2" aria-label="Memory pages">{["evidence", "observations", "candidates", "cases", "patterns", "playbooks"].map((item) => <Link key={item} to={listPath(item)} className={`rounded-ctl px-3 py-2 text-sm ${section === item ? "bg-mint text-ink" : "border border-white/10 text-muted hover:border-white/20"}`}>{item === "candidates" ? "Candidate insights" : item[0].toUpperCase() + item.slice(1)}</Link>)}</nav>
    {scopeLoading ? <div className="mt-5"><StatePanel state="loading" message="Loading project scope..." /></div> : projectId ? <div className="mt-5"><ProjectList section={section} projectId={projectId} environment={environment} onSelect={(id) => { const next = new URLSearchParams(params); next.set("document", id); navigate(`/knowledge/${section}?${next.toString()}`); }} /></div> : <div className="mt-5"><StatePanel state="empty" message="Select a project to inspect records. Use Memory workspace for candidate insights and confirmed memory." /></div>}
    <Drawer open={Boolean(selected && projectId)} onClose={() => navigate(listPath(section))} title={title}>
      {selected && projectId && (section === "evidence" ? <EvidenceDetail id={selected} onBack={() => navigate(listPath("evidence"))} /> : section === "observations" ? <ObservationDetail id={selected} onBack={() => navigate(listPath("observations"))} /> : <KnowledgeDetail id={selected} projectId={projectId} kind={detailKind} onBack={() => navigate(listPath(section))} onReview={review} />)}
    </Drawer>
  </div>;
}
